// Package pyjson encodes values exactly like Python's json.dumps (default separators, ensure_ascii),
// so data files regenerated by kblva are byte-identical to the ones the Python tools wrote.
package pyjson

import (
	"bytes"
	"encoding/json"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"unicode/utf16"
)

// OrderedMap is a JSON object that keeps key order.
type OrderedMap struct {
	Keys   []string
	Values map[string]any
}

func NewOrdered() *OrderedMap { return &OrderedMap{Values: map[string]any{}} }

func (m *OrderedMap) Set(k string, v any) {
	if _, ok := m.Values[k]; !ok {
		m.Keys = append(m.Keys, k)
	}
	m.Values[k] = v
}

func (m *OrderedMap) Get(k string) (any, bool) {
	if m == nil {
		return nil, false
	}
	v, ok := m.Values[k]
	return v, ok
}

// String returns the value at k if it is a non-empty string.
func (m *OrderedMap) String(k string) string {
	v, _ := m.Get(k)
	s, _ := v.(string)
	return s
}

func (m *OrderedMap) UnmarshalJSON(b []byte) error {
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("pyjson: expected object")
	}
	m.Keys, m.Values = nil, map[string]any{}
	for dec.More() {
		kt, err := dec.Token()
		if err != nil {
			return err
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return err
		}
		v, err := decodeAny(raw)
		if err != nil {
			return err
		}
		m.Set(kt.(string), v)
	}
	return nil
}

func decodeAny(raw json.RawMessage) (any, error) {
	t := bytes.TrimSpace(raw)
	if len(t) > 0 && t[0] == '{' {
		m := NewOrdered()
		return m, m.UnmarshalJSON(t)
	}
	if len(t) > 0 && t[0] == '[' {
		var rs []json.RawMessage
		if err := json.Unmarshal(t, &rs); err != nil {
			return nil, err
		}
		out := make([]any, len(rs))
		for i, r := range rs {
			v, err := decodeAny(r)
			if err != nil {
				return nil, err
			}
			out[i] = v
		}
		return out, nil
	}
	dec := json.NewDecoder(bytes.NewReader(t))
	dec.UseNumber()
	var v any
	return v, dec.Decode(&v)
}

// Ordered lets a record choose its own keys, for objects whose key set varies (present-but-null vs absent).
type Ordered interface{ PyOrdered() *OrderedMap }

// Marshal encodes like json.dumps(v). indent<=0 means the single-line default form.
func Marshal(v any, indent int) ([]byte, error) {
	var b bytes.Buffer
	if err := enc(&b, reflect.ValueOf(v), indent, 0); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}

func nl(b *bytes.Buffer, indent, depth int) {
	b.WriteByte('\n')
	b.WriteString(strings.Repeat(" ", indent*depth))
}

func enc(b *bytes.Buffer, v reflect.Value, indent, depth int) error {
	if !v.IsValid() {
		b.WriteString("null")
		return nil
	}
	if m, ok := v.Interface().(*OrderedMap); ok {
		if m == nil {
			b.WriteString("null")
			return nil
		}
		return encMap(b, m.Keys, func(k string) (reflect.Value, error) { return reflect.ValueOf(m.Values[k]), nil }, indent, depth)
	}
	if o, ok := v.Interface().(Ordered); ok {
		m := o.PyOrdered()
		return encMap(b, m.Keys, func(k string) (reflect.Value, error) { return reflect.ValueOf(m.Values[k]), nil }, indent, depth)
	}
	if n, ok := v.Interface().(json.Number); ok {
		b.WriteString(n.String())
		return nil
	}
	switch v.Kind() {
	case reflect.Interface, reflect.Pointer:
		if v.IsNil() {
			b.WriteString("null")
			return nil
		}
		return enc(b, v.Elem(), indent, depth)
	case reflect.Bool:
		b.WriteString(strconv.FormatBool(v.Bool()))
	case reflect.String:
		str(b, v.String())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		b.WriteString(strconv.FormatUint(v.Uint(), 10))
	case reflect.Slice, reflect.Array:
		if v.Kind() == reflect.Slice && v.IsNil() {
			b.WriteString("[]")
			return nil
		}
		if v.Len() == 0 {
			b.WriteString("[]")
			return nil
		}
		b.WriteByte('[')
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				b.WriteString(sep(indent))
			}
			if indent > 0 {
				nl(b, indent, depth+1)
			}
			if err := enc(b, v.Index(i), indent, depth+1); err != nil {
				return err
			}
		}
		if indent > 0 {
			nl(b, indent, depth)
		}
		b.WriteByte(']')
	case reflect.Struct:
		var keys []string
		fields := map[string]reflect.Value{}
		t := v.Type()
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			tag := f.Tag.Get("json")
			if tag == "-" || !f.IsExported() {
				continue
			}
			name, opts, _ := strings.Cut(tag, ",")
			if name == "" {
				name = f.Name
			}
			fv := v.Field(i)
			if strings.Contains(opts, "omitempty") && isEmpty(fv) {
				continue
			}
			keys = append(keys, name)
			fields[name] = fv
		}
		return encMap(b, keys, func(k string) (reflect.Value, error) { return fields[k], nil }, indent, depth)
	default:
		return fmt.Errorf("pyjson: unsupported kind %s", v.Kind())
	}
	return nil
}

func sep(indent int) string {
	if indent > 0 {
		return ","
	}
	return ", "
}

func encMap(b *bytes.Buffer, keys []string, get func(string) (reflect.Value, error), indent, depth int) error {
	if len(keys) == 0 {
		b.WriteString("{}")
		return nil
	}
	b.WriteByte('{')
	for i, k := range keys {
		if i > 0 {
			b.WriteString(sep(indent))
		}
		if indent > 0 {
			nl(b, indent, depth+1)
		}
		str(b, k)
		b.WriteString(": ")
		fv, err := get(k)
		if err != nil {
			return err
		}
		if err := enc(b, fv, indent, depth+1); err != nil {
			return err
		}
	}
	if indent > 0 {
		nl(b, indent, depth)
	}
	b.WriteByte('}')
	return nil
}

func isEmpty(v reflect.Value) bool {
	switch v.Kind() {
	case reflect.Pointer, reflect.Interface, reflect.Slice, reflect.Map:
		return v.IsNil() || (v.Kind() == reflect.Slice && v.Len() == 0)
	case reflect.String:
		return v.Len() == 0
	case reflect.Bool:
		return !v.Bool()
	case reflect.Int, reflect.Int64:
		return v.Int() == 0
	}
	return false
}

const hex = "0123456789abcdef"

func str(b *bytes.Buffer, s string) {
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r == '\n':
			b.WriteString(`\n`)
		case r == '\r':
			b.WriteString(`\r`)
		case r == '\t':
			b.WriteString(`\t`)
		case r == '\b':
			b.WriteString(`\b`)
		case r == '\f':
			b.WriteString(`\f`)
		case r < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte(hex[r>>4])
			b.WriteByte(hex[r&0xf])
		case r < 0x80:
			b.WriteRune(r)
		case r > 0xffff:
			r1, r2 := utf16.EncodeRune(r)
			fmt.Fprintf(b, `\u%04x\u%04x`, r1, r2)
		default:
			fmt.Fprintf(b, `\u%04x`, r)
		}
	}
	b.WriteByte('"')
}
